<?php
require '../config/database.php';require '../includes/auth.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,['approved','rejected','pending'],true)){$s=$pdo->prepare('UPDATE claims SET status=? WHERE id=?');$s->execute([$status,$id]);if($status==='approved'){$q=$pdo->prepare("UPDATE items SET status='returned' WHERE id=(SELECT item_id FROM claims WHERE id=?)");$q->execute([$id]);}}}
$claims=$pdo->query('SELECT c.*,i.title,u.name AS claimant,u.email FROM claims c JOIN items i ON i.id=c.item_id JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC')->fetchAll();
$pageTitle='Manage claims';$assetPrefix='../';$homePrefix='../';require '../includes/header.php';?>
<div class="dashboard-head"><div><span class="eyebrow">ADMIN TOOLS</span><h1>Ownership claims</h1><p class="muted">Review the claimant's explanation before making a decision.</p></div></div>
<div class="table-wrap"><table><thead><tr><th>Item</th><th>Claimant</th><th>Claim message</th><th>Decision</th></tr></thead><tbody><?php foreach($claims as $c):?><tr><td><?=e($c['title'])?></td><td><?=e($c['claimant'])?><br><small><?=e($c['email'])?></small></td><td><?=e($c['message'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><select name="status"><?php foreach(['pending','approved','rejected'] as $st):?><option value="<?=$st?>" <?=$c['status']===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach;?></select><button class="btn btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$claims):?><div class="empty-state">No claims have been submitted.</div><?php endif;?></div>
